   $('#rs').innerHTML=`<b>${R0.title}</b> — ${rows.length} ${$('#rtype').value=='activities'?'activities':'students'}`+($('#rtype').value=='honors'?` · ${rows.filter(r=>r[5].startsWith('Eligible')).length} eligible (preliminary) · ${rows.filter(r=>r[5]=='Needs Review').length} need review`:$('#rtype').value=='cocurricular'?' · counts include verified activities only':'');
