// ---- Module 4 shared helpers (used by the Admin and Student co-curricular pages) ----
const esc=t=>String(t==null?'':t).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const vpill=v=>pill(v,VERIFY[v]||'b');
const CO_NOTE='<div class=note><i class="bi bi-info-circle"></i> Summaries count <b>verified</b> activities only. There is <b>no co-curricular score</b>: this module records, verifies and counts activities. Activity records are kept in this browser.</div>';
// activity table. opts.student = show Student column, opts.admin = show Edit / Delete buttons
const actTable=(list,o={})=>{const btn=a=>`<button class="btn btn-sm btn-o av" data-a=${a.aid} title="View details"><i class="bi bi-eye"></i></button>`+(o.admin?` <button class="btn btn-sm btn-o ae" data-a=${a.aid} title="Edit"><i class="bi bi-pencil"></i></button> <button class="btn btn-sm btn-o ad" data-a=${a.aid} title="Delete"><i class="bi bi-trash"></i></button>`:'');
 if(!list.length)return'<div class="text-center text-muted py-4">No activity records found.</div>';
 return tbl([...(o.student?['Activity ID','Student']:[]),'Activity','Category','Level','Academic Year','Recognition','Verification','Actions'],list.map(a=>[...(o.student?[a.aid,`${a.sid} · ${esc(studentName(a.sid))}`]:[]),`<b>${esc(a.title)}</b>${a.org||a.role?`<br><small class=text-muted>${esc([a.org,a.role].filter(Boolean).join(' · '))}</small>`:''}`,esc(a.cat),esc(a.level),esc(a.year),esc(a.achv||'—'),vpill(a.ver),btn(a)]))};
const actDetail=a=>`<div class=row><div class="col-md-6"><p class=mb-1><b>${esc(a.title)}</b></p><p class="small mb-2">Activity ID ${a.aid}<br>Student: ${a.sid} · ${esc(studentName(a.sid))}</p><p class=mb-1>${vpill(a.ver)}</p></div><div class="col-md-6 small"><b>Category:</b> ${esc(a.cat)}<br><b>Organization / event:</b> ${esc(a.org||'—')}<br><b>Position / role:</b> ${esc(a.role||'—')}<br><b>Participation level:</b> ${esc(a.level)}<br><b>Academic year:</b> ${esc(a.year)}<br><b>Achievement / recognition:</b> ${esc(a.achv||'—')}</div></div><p class="small mt-2 mb-0"><b>Description:</b> ${esc(a.desc||'—')}</p>`;
const GROUP_ICONS=[['Leadership','people','p'],['Organization','diagram-3','b'],['Community','heart','r'],['Competitions','trophy','p'],['Training','award','o']];
const groupCards=sm=>`<div class="panel d-flex flex-wrap gap-2 mb-2">${GROUP_ICONS.map(g=>`<div class=cat><i class="bi bi-${g[1]} pill ${g[2]}"></i><br>${g[0]}<br><b>${sm.groups[g[0]]}</b></div>`).join('')}</div><div class="small text-muted mb-3">Cards count <b>verified</b> activities only. Verified: ${sm.verified} · Pending: ${sm.pending} · Rejected: ${sm.rejected}</div>`;
const profileCard=s=>`<div class="text-center"><i class="bi bi-person-circle avatar-lg"></i></div><p class="text-center mb-0 mt-2"><b>${esc(s.name)}</b><br>${esc(s.prog)} - Year ${s.yr} - Section ${esc(s.sec)}<br>Student ID: ${s.id}</p>`;
// Holistic summary = verified co-curricular counts + the academic results of Modules 1-3. No combined score is calculated.
const holistic=s=>{const sm=coSummary(s.id),e=evaluateHonors(s),t=analyzeStudent(s);return`<b>Holistic Evaluation Summary</b><ul class="list-unstyled small mt-2"><li><b>Co-curricular</b></li><li>Verified activities: <b>${sm.verified}</b> of ${sm.total} recorded</li><li>Pending: ${sm.pending} · Rejected: ${sm.rejected}</li><li>Highest verified level: <b>${sm.highest||'—'}</b></li><li class=mt-2><b>Academic (Modules 1–3)</b></li><li>Latest GWA: <b>${fx(curGWA(s))}</b></li><li>Honors screening: ${pill(STATUS[e.key][0],STATUS[e.key][1])}</li><li>Performance trend: ${pill(t.trend,{Improving:'g',Stable:'b',Declining:'y','Insufficient Data':'p'}[t.trend])}</li></ul><small class=text-muted>Information only: PLMun has not confirmed a rubric for combining these, so no score or ranking is calculated.</small>`};
